@startuml

class Location {
  + address : string
}

class Driver {
  + firstName : string
  + lastName : string
}

class Vehicle {
  + vehicleNumber : string
}

class Truck extends Vehicle {
  + weight : float
}

class Car extends Vehicle {
  + numberOfSeats : int
}

class Van extends Vehicle {
}

class Order {
  + originLocation : Location
  + destinationLocation : Location
  + dateOfExecution : date
}

Location "1" *-- "*" Driver
Location "1" *-- "*" Vehicle
Driver "1" -- "0..1" Order : carries out
Driver "1" -- "0..1" Vehicle : drives
Order "*" -- "1..*" Driver : assigned to
@enduml

